test("sink end-to-end: captures, replies, redacts on disk", async () => {
  const captureDir = mkdtempSync(join(tmpdir(), "sat-sink-"));
  const seen = [];
  const { server, port } = await startSink({ port: 0, captureDir, onCapture: (c) => seen.push(c) });
  const url = (p) => `http://127.0.0.1:${port}${p}`;

  const res = await fetch(url("/v1/messages"), {
    method: "POST",
    headers: { "content-type": "application/json", "x-api-key": "sk-super-secret" },
    body: JSON.stringify({ model: "claude-opus-5", system: "s", tools: [], messages: [] }),
  });
  const body = await res.json();
  assert.equal(body.type, "message");
  assert.equal(body.stop_reason, "end_turn");
  assert.equal(body.content[0].text, "DONE");

  const sse = await fetch(url("/v1/responses"), {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ model: "gpt-5.5", stream: true, instructions: "i", input: [] }),
  });
  const text = await sse.text();
  assert.ok(sse.headers.get("content-type").includes("text/event-stream"));
  assert.ok(text.includes("event: response.created"));
  assert.ok(text.includes("event: response.completed"));
  assert.ok(text.includes('"DONE"'));

  const chat = await fetch(url("/v1/chat/completions"), {
    method: "POST",
    body: JSON.stringify({ model: "gpt-4o", stream: true, messages: [] }),
  });
  const chatText = await chat.text();
  assert.ok(chatText.trimEnd().endsWith("data: [DONE]"));

  const gem = await fetch(url("/v1beta/models/gemini-2.5-pro:generateContent"), {
    method: "POST",
    body: JSON.stringify({ contents: [] }),
  });
  const gemBody = await gem.json();
  assert.equal(gemBody.candidates[0].finishReason, "STOP");

  server.close();

  const files = readdirSync(captureDir).sort();
  assert.equal(files.length, 4);
  assert.equal(seen.length, 4);
  const first = JSON.parse(readFileSync(join(captureDir, files[0]), "utf8"));
  assert.equal(first.kind, "anthropic-messages");
  assert.equal(first.body.model, "claude-opus-5");
  for (const f of files) {
    assert.ok(!readFileSync(join(captureDir, f), "utf8").includes("sk-super-secret"), `${f} leaked a secret`);
  }
});

import { test } from "node:test";
import assert from "node:assert/strict";

import { estimateTokens, buildCountTokensRequest, countTokensAnthropic, DEFAULT_CHARS_PER_TOKEN } from "../lib/tokens.mjs";
import { startSink } from "../lib/sink.mjs";

test("estimateTokens math and labeling", () => {
  const est = estimateTokens(64000);
  assert.equal(est.basis, "est");
  assert.equal(est.ratio, DEFAULT_CHARS_PER_TOKEN);
  assert.equal(est.tokens, Math.round(64000 / DEFAULT_CHARS_PER_TOKEN));
  assert.equal(estimateTokens(100, 5).tokens, 20);
  assert.throws(() => estimateTokens(100, 0));
});

test("buildCountTokensRequest passes captured fields through verbatim", () => {
  const body = { model: "claude-opus-5", system: "s", tools: [{ name: "t" }], messages: [{ role: "user", content: "hi" }], stream: true, max_tokens: 5 };
  const req = buildCountTokensRequest(body);
  assert.deepEqual(Object.keys(req).sort(), ["messages", "model", "system", "tools"]);
  assert.equal(req.system, body.system);
  assert.equal(req.tools, body.tools);
  assert.equal(buildCountTokensRequest({ system: "no model or messages" }), null);
});

test("countTokensAnthropic against a local endpoint; never guesses on error", async () => {
  const { server, port } = await startSink({ port: 0 });
  const ok = await countTokensAnthropic(
    { model: "m", messages: [{ role: "user", content: "hi" }] },
    { apiKey: "k", baseUrl: `http://127.0.0.1:${port}` },
  );
  assert.equal(ok.basis, "exact");
  assert.equal(typeof ok.tokens, "number");
  server.close();

  const bad = await countTokensAnthropic({ notCountable: true }, { apiKey: "k", baseUrl: "http://127.0.0.1:1" });
  assert.ok(bad.error);
  assert.equal(bad.tokens, undefined);
});
